-- ===========================================================================
-- schema.sql — the Checkpoint Outfitters database.
--
-- Checkpoint Outfitters is a FICTIONAL adventure-racing gear shop: trail
-- shoes, packs, headlamps, navigation, paddle and bike kit. Every person,
-- brand, street and email in this database is invented.
--
-- This file is the readable copy of the structure, and it is the one
-- `npm run seed` actually executes — so what you read here is exactly what
-- the database contains. The data itself is generated by scripts/seed.ts.
--
-- Five tables:
--
--   customers ──< addresses          one billing + some shipping addresses
--       │
--       └──────< orders >── addresses  each order ships to one address
--                   │
--                   └──< order_items >── products
--
-- The data server opens this database READ-ONLY. Nothing the model does
-- can change a row; that is enforced by how the file is opened, not by
-- asking the model nicely.
--
-- ---------------------------------------------------------------------------
-- Conventions used throughout
-- ---------------------------------------------------------------------------
--
-- STRICT tables. By default SQLite will store any value in any column — a
-- string in an INTEGER column is accepted without complaint. STRICT makes
-- the declared types binding, which is what most people assume SQL does
-- anyway.
--
-- Money is INTEGER CENTS, never a floating-point number of dollars. In
-- floating point 0.1 + 0.2 is 0.30000000000000004; add up a few thousand
-- order lines and the totals stop matching to the cent. Integers add up
-- exactly. Divide by 100 only when displaying.
--
-- Dates are TEXT in ISO 8601 ("2026-11-18" or "2026-11-18T14:05:00Z").
-- SQLite has no date type. ISO 8601 strings sort in date order as plain
-- text, which is what makes `placed_at >= '2026-10-01'` work.
--
-- Booleans are INTEGER 0 or 1, with a CHECK to keep them that way. SQLite
-- has no boolean type either.
--
-- Foreign keys are declared, but SQLite only ENFORCES them on a connection
-- that has run `PRAGMA foreign_keys = ON`. The seed turns it on; without it
-- every REFERENCES clause below would be documentation only.
-- ===========================================================================


-- ---------------------------------------------------------------------------
-- customers — the people who buy things.
-- ---------------------------------------------------------------------------
CREATE TABLE customers (
  id          INTEGER PRIMARY KEY,
  first_name  TEXT    NOT NULL,
  last_name   TEXT    NOT NULL,

  -- Unique, because it is how a support rep (and the model) looks a
  -- customer up. Names are NOT unique — two customers in this data share
  -- one, deliberately — which is why lookups by name return a list.
  -- All on example.com, a domain reserved for documentation.
  email       TEXT    NOT NULL UNIQUE,

  -- 555-01xx numbers are reserved for fiction; none of these ring anyone.
  phone       TEXT    NOT NULL,

  -- Date only (YYYY-MM-DD).
  joined_at   TEXT    NOT NULL
) STRICT;


-- ---------------------------------------------------------------------------
-- addresses — where customers are billed and where orders are sent.
-- ---------------------------------------------------------------------------
CREATE TABLE addresses (
  id           INTEGER PRIMARY KEY,
  customer_id  INTEGER NOT NULL REFERENCES customers (id),
  kind         TEXT    NOT NULL CHECK (kind IN ('billing', 'shipping')),

  -- What the customer calls it: "Home", "Work", "Mum's place".
  label        TEXT    NOT NULL,
  street       TEXT    NOT NULL,
  city         TEXT    NOT NULL,
  state        TEXT    NOT NULL,   -- two-letter US state code
  zip          TEXT    NOT NULL,   -- TEXT, not INTEGER: "02134" keeps its 0

  -- For shipping addresses, the one used when nothing else is chosen.
  -- A billing address is always its own default.
  is_default   INTEGER NOT NULL DEFAULT 0 CHECK (is_default IN (0, 1)),

  -- Not a real-world need: this exists so orders can declare a composite
  -- foreign key (shipping_address_id, customer_id) below. A foreign key
  -- must point at a UNIQUE set of columns, and (id, customer_id) is unique
  -- because id alone already is.
  UNIQUE (id, customer_id)
) STRICT;

-- One billing address per customer.
--
-- A PARTIAL unique index: unique on customer_id, but only among rows where
-- kind = 'billing'. Shipping rows are not in the index at all, so a
-- customer can have any number of those.
--
-- Note what this does NOT enforce. It guarantees AT MOST one billing
-- address; it cannot guarantee AT LEAST one, because a constraint checks
-- rows that exist and has nothing to say about a row that is missing. The
-- seed checks that every customer has one. That gap is a real limit of
-- declarative constraints, not an oversight here.
CREATE UNIQUE INDEX addresses_one_billing
  ON addresses (customer_id) WHERE kind = 'billing';

-- At most one DEFAULT shipping address per customer — the same trick.
CREATE UNIQUE INDEX addresses_one_default_shipping
  ON addresses (customer_id) WHERE kind = 'shipping' AND is_default = 1;

CREATE INDEX addresses_customer ON addresses (customer_id);


-- ---------------------------------------------------------------------------
-- products — the catalogue.
-- ---------------------------------------------------------------------------
CREATE TABLE products (
  id            INTEGER PRIMARY KEY,

  -- The shop's own product code, e.g. "CO-TRL-007". What a rep types.
  sku           TEXT    NOT NULL UNIQUE,
  name          TEXT    NOT NULL,
  category      TEXT    NOT NULL,
  brand         TEXT    NOT NULL,   -- invented brands; no real trademarks

  -- The CURRENT price. What a past order paid lives on order_items.
  price_cents   INTEGER NOT NULL CHECK (price_cents > 0),

  weight_grams  INTEGER NOT NULL CHECK (weight_grams > 0),
  color         TEXT    NOT NULL,

  -- Free text, and therefore UNTRUSTED when it reaches the model. One
  -- product's description contains an injected instruction on purpose —
  -- see scripts/seed.ts — to show that data arriving through a tool can
  -- try to steer the model as well as inform it.
  description   TEXT    NOT NULL,

  -- No longer sold, but kept: old orders still point at it, and deleting
  -- it would break their history.
  discontinued  INTEGER NOT NULL DEFAULT 0 CHECK (discontinued IN (0, 1))
) STRICT;

CREATE INDEX products_category ON products (category);


-- ---------------------------------------------------------------------------
-- orders — one row per checkout.
-- ---------------------------------------------------------------------------
CREATE TABLE orders (
  id                   INTEGER PRIMARY KEY,

  -- What the customer sees on their receipt, e.g. "CP-10234". The id is
  -- internal; the order number is what people quote on the phone.
  order_number         TEXT    NOT NULL UNIQUE,
  customer_id          INTEGER NOT NULL REFERENCES customers (id),
  shipping_address_id  INTEGER NOT NULL,

  -- Full timestamp, UTC.
  placed_at            TEXT    NOT NULL,

  status               TEXT    NOT NULL CHECK (status IN (
                         'pending', 'processing', 'shipped',
                         'delivered', 'cancelled', 'returned')),

  -- Stored, not computed on the fly, for the same reason as
  -- order_items.unit_price_cents: these are the amounts that were actually
  -- charged. Recomputing them later from current tax rules or shipping
  -- rates would rewrite history. total = subtotal + shipping + tax.
  subtotal_cents       INTEGER NOT NULL CHECK (subtotal_cents >= 0),
  shipping_cents       INTEGER NOT NULL CHECK (shipping_cents >= 0),
  tax_cents            INTEGER NOT NULL CHECK (tax_cents >= 0),
  total_cents          INTEGER NOT NULL CHECK (
                         total_cents = subtotal_cents + shipping_cents + tax_cents),

  -- The order must ship to an address belonging to THE SAME customer.
  -- A plain `shipping_address_id REFERENCES addresses (id)` would accept
  -- anyone's address. Pointing the PAIR at the pair closes that gap.
  -- (It cannot also check that the address is a shipping one, not a
  -- billing one; the seed verifies that.)
  FOREIGN KEY (shipping_address_id, customer_id)
    REFERENCES addresses (id, customer_id)
) STRICT;

CREATE INDEX orders_customer  ON orders (customer_id);
CREATE INDEX orders_address   ON orders (shipping_address_id);
CREATE INDEX orders_placed_at ON orders (placed_at);
CREATE INDEX orders_status    ON orders (status);


-- ---------------------------------------------------------------------------
-- order_items — the lines on an order.
-- ---------------------------------------------------------------------------
CREATE TABLE order_items (
  id                INTEGER PRIMARY KEY,
  order_id          INTEGER NOT NULL REFERENCES orders (id),
  product_id        INTEGER NOT NULL REFERENCES products (id),
  quantity          INTEGER NOT NULL CHECK (quantity > 0),

  -- A SNAPSHOT of the price paid, copied from products.price_cents at the
  -- moment of sale. Prices change; this does not. Joining to
  -- products.price_cents to work out what an old order cost would quietly
  -- give today's price — some older orders here deliberately paid less
  -- than the current price, so that mistake shows up in the numbers.
  unit_price_cents  INTEGER NOT NULL CHECK (unit_price_cents > 0)
) STRICT;

CREATE INDEX order_items_order   ON order_items (order_id);
CREATE INDEX order_items_product ON order_items (product_id);
